from collections.abc import Mapping, MutableMapping, MutableSequence, MutableSet
from importlib.metadata import version
from pathlib import Path
import sys
from typing import Generic, TypeVar

import pydandict
from pydantic import BaseModel, Field, ValidationError
from pydandict import DictModel

assert version("pydandict") == "0.2.0"
assert Path(pydandict.__file__).resolve().is_relative_to(Path(sys.prefix).resolve())


class User(DictModel):
    name: str
    age: int = Field(ge=0)


user = User(name="Eddie", age=40)
assert isinstance(user, BaseModel) and isinstance(user, Mapping)
user["age"] = 41
assert user.age == user["age"] == 41
try:
    user["age"] = -1
except ValidationError:
    assert user.age == 41
else:
    raise AssertionError("invalid quickstart edit committed")
assert dict(user) == {"name": "Eddie", "age": 41}


class Settings(DictModel):
    retries: MutableSequence[int] = Field(default_factory=list)
    groups: MutableMapping[str, MutableSequence[int]] = Field(default_factory=dict)
    flags: MutableSet[str] = Field(default_factory=set)


settings = Settings(retries=[1], groups={"primary": [2]}, flags={"ready"})
settings.groups["primary"].append(3)
settings.flags.add("done")
assert settings.model_dump() == {
    "retries": [1], "groups": {"primary": [2, 3]}, "flags": {"ready", "done"}
}
before = settings.model_dump()
try:
    settings.retries.append("bad")
except ValidationError:
    assert settings.model_dump() == before
else:
    raise AssertionError("invalid migrated edit committed")

T = TypeVar("T")


class Box(DictModel, Generic[T]):
    value: T


box = Box[MutableSequence[int]](value=[1])
box.value.append(2)
assert box.model_dump() == {"value": [1, 2]}
try:
    Box(value=1)
except TypeError as error:
    assert str(error).startswith("pydandict_unsupported_annotation:")
else:
    raise AssertionError("unbound generic construction accepted")

print("installed 0.2.0 quickstart, ABC migration and generic smoke checks passed")
